package auth

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"fmt"
	"net/http"
	"strings"
	"sync"
	"time"
)

var (
	ErrInvalidToken  = errors.New("invalid token")
	ErrExpiredToken  = errors.New("token expired")
	ErrInvalidSig    = errors.New("invalid signature")
	ErrWeakSecret    = errors.New("secret key too short: minimum 32 bytes required")
)

// minSecretLen is the minimum acceptable HMAC secret length in bytes.
const minSecretLen = 32

// Custom base64url alphabet (RFC 4648 §5 compatible)
const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"

var decodeMap [256]byte

func init() {
	for i := range decodeMap {
		decodeMap[i] = 0xFF
	}
	for i, c := range alphabet {
		decodeMap[c] = byte(i)
	}
}

// encode encodes bytes to our custom base64url without padding
func encode(data []byte) string {
	var sb strings.Builder
	for i := 0; i < len(data); i += 3 {
		remaining := len(data) - i
		var b0, b1, b2 byte
		b0 = data[i]
		if remaining > 1 {
			b1 = data[i+1]
		}
		if remaining > 2 {
			b2 = data[i+2]
		}
		sb.WriteByte(alphabet[b0>>2])
		sb.WriteByte(alphabet[((b0&0x03)<<4)|(b1>>4)])
		if remaining > 1 {
			sb.WriteByte(alphabet[((b1&0x0F)<<2)|(b2>>6)])
		}
		if remaining > 2 {
			sb.WriteByte(alphabet[b2&0x3F])
		}
	}
	return sb.String()
}

// decode decodes our custom base64url string back to bytes
func decode(s string) ([]byte, error) {
	if len(s) == 0 {
		return nil, errors.New("empty input")
	}
	// Calculate output length based on input length
	result := make([]byte, 0, (len(s)*3)/4+3)

	for i := 0; i < len(s); i += 4 {
		var vals [4]byte
		var validChars int

		for j := 0; j < 4 && i+j < len(s); j++ {
			v := decodeMap[s[i+j]]
			if v == 0xFF {
				return nil, fmt.Errorf("invalid character at position %d", i+j)
			}
			vals[j] = v
			validChars++
		}

		if validChars >= 2 {
			result = append(result, (vals[0]<<2)|(vals[1]>>4))
		}
		if validChars >= 3 {
			result = append(result, (vals[1]<<4)|(vals[2]>>2))
		}
		if validChars >= 4 {
			result = append(result, (vals[2]<<6)|vals[3])
		}
	}

	// Trim trailing zero bytes that result from incomplete blocks
	switch len(s) % 4 {
	case 2:
		if len(result) >= 2 {
			result = result[:len(result)-2]
		}
	case 3:
		if len(result) >= 1 {
			result = result[:len(result)-1]
		}
	}

	return result, nil
}

// TokenPayload represents the claims in our token
type TokenPayload struct {
	UserID    uint32
	Role      byte // 0=user, 1=admin
	IssuedAt  int64
	ExpiresAt int64
}

func serializePayload(p *TokenPayload) []byte {
	buf := make([]byte, 21)
	binary.BigEndian.PutUint32(buf[0:4], p.UserID)
	buf[4] = p.Role
	binary.BigEndian.PutUint64(buf[5:13], uint64(p.IssuedAt))
	binary.BigEndian.PutUint64(buf[13:21], uint64(p.ExpiresAt))
	return buf
}

func deserializePayload(data []byte) (*TokenPayload, error) {
	if len(data) < 21 {
		return nil, errors.New("payload too short")
	}
	p := &TokenPayload{
		UserID:    binary.BigEndian.Uint32(data[0:4]),
		Role:      data[4],
		IssuedAt:  int64(binary.BigEndian.Uint64(data[5:13])),
		ExpiresAt: int64(binary.BigEndian.Uint64(data[13:21])),
	}
	return p, nil
}

// TokenService manages token creation and validation
type TokenService struct {
	secretKey []byte
	mu        sync.RWMutex
	revoked   map[string]bool
}

// NewTokenService creates a TokenService. It returns an error if the provided
// secret is too short to serve as a secure HMAC key.
func NewTokenService(secret string) (*TokenService, error) {
	if len(secret) < minSecretLen {
		return nil, ErrWeakSecret
	}
	return &TokenService{
		secretKey: []byte(secret),
		revoked:   make(map[string]bool),
	}, nil
}

// computeSignature generates HMAC-SHA256 of the payload
func (ts *TokenService) computeSignature(payloadBytes []byte) []byte {
	mac := hmac.New(sha256.New, ts.secretKey)
	mac.Write(payloadBytes)
	return mac.Sum(nil)
}

// IssueToken creates a signed token for the given user
func (ts *TokenService) IssueToken(userID uint32, role byte, ttl time.Duration) string {
	now := time.Now().Unix()
	payload := &TokenPayload{
		UserID:    userID,
		Role:      role,
		IssuedAt:  now,
		ExpiresAt: now + int64(ttl.Seconds()),
	}
	payloadBytes := serializePayload(payload)
	sig := ts.computeSignature(payloadBytes)

	// Token format: base64url(payload).base64url(signature)
	return encode(payloadBytes) + "." + encode(sig)
}

// ValidateToken parses and validates a token, returning the payload
func (ts *TokenService) ValidateToken(token string) (*TokenPayload, error) {
	parts := strings.SplitN(token, ".", 2)
	if len(parts) != 2 {
		return nil, ErrInvalidToken
	}

	payloadEncoded := parts[0]
	sigEncoded := parts[1]

	// Decode payload
	payloadBytes, err := decode(payloadEncoded)
	if err != nil {
		return nil, ErrInvalidToken
	}

	// Decode signature
	sigBytes, err := decode(sigEncoded)
	if err != nil {
		return nil, ErrInvalidToken
	}

	// Recompute signature from the raw encoded payload string
	// This ensures we verify exactly what was transmitted
	expectedSig := ts.computeSignature([]byte(payloadEncoded))

	// Constant-time comparison of signature bytes
	if !hmac.Equal(sigBytes, expectedSig) {
		return nil, ErrInvalidSig
	}

	// Deserialize and validate payload
	payload, err := deserializePayload(payloadBytes)
	if err != nil {
		return nil, ErrInvalidToken
	}

	// Check expiration
	if time.Now().Unix() > payload.ExpiresAt {
		return nil, ErrExpiredToken
	}

	// Check revocation
	ts.mu.RLock()
	tokenID := fmt.Sprintf("%d-%d", payload.UserID, payload.IssuedAt)
	if ts.revoked[tokenID] {
		ts.mu.RUnlock()
		return nil, ErrInvalidToken
	}
	ts.mu.RUnlock()

	return payload, nil
}

// RevokeToken marks a token as revoked
func (ts *TokenService) RevokeToken(userID uint32, issuedAt int64) {
	ts.mu.Lock()
	defer ts.mu.Unlock()
	tokenID := fmt.Sprintf("%d-%d", userID, issuedAt)
	ts.revoked[tokenID] = true
}

// AuthMiddleware validates tokens and sets user context
func (ts *TokenService) AuthMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Strip any client-supplied identity headers to prevent spoofing
		// before authentication has established the real identity.
		r.Header.Del("X-User-ID")
		r.Header.Del("X-User-Role")

		authHeader := r.Header.Get("Authorization")
		if !strings.HasPrefix(authHeader, "Bearer ") {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}

		token := strings.TrimPrefix(authHeader, "Bearer ")
		payload, err := ts.ValidateToken(token)
		if err != nil {
			http.Error(w, err.Error(), http.StatusUnauthorized)
			return
		}

		// Set headers for downstream handlers
		r.Header.Set("X-User-ID", fmt.Sprintf("%d", payload.UserID))
		r.Header.Set("X-User-Role", fmt.Sprintf("%d", payload.Role))
		next.ServeHTTP(w, r)
	})
}

// AdminHandler only allows admin users
func AdminHandler(w http.ResponseWriter, r *http.Request) {
	role := r.Header.Get("X-User-Role")
	if role != "1" {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	w.Write([]byte("admin access granted"))
}
